/**
 * EVENTTWIN ML MODEL (brain.js Neural Network)
 * 
 * Pure-JavaScript ML inference — no Python required.
 * Uses brain.js NeuralNetwork for zone-demand forecasting.
 * 
 * FEATURES:
 *   - Loads training data from CSV generated by dataGenerator.js
 *   - Min-max normalization for stable gradient convergence
 *   - Trains a multi-output regression network (3 outputs: future zone demands)
 *   - Saves/loads trained weights as JSON for instant startup
 *   - Inference produces the same structure as fallbackForecast.js
 *
 * ARCHITECTURE:
 *   Input (13 features) → Hidden(26) → Hidden(16) → Output(3)
 *   Features: visitor_count, zone_a/b/c_demand, venue/transit/parking/hotel loads,
 *             rain_factor, transit_disruption, parking_reduction, venue_delay, visitor_growth
 *   Targets:  future_zone_a_demand, future_zone_b_demand, future_zone_c_demand
 */

import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

// ──────────────────────────────────────
// PATHS
// ──────────────────────────────────────
const DATA_DIR = path.join(__dirname, 'data');
const TRAINING_CSV = path.join(DATA_DIR, 'training_data.csv');
const MODEL_WEIGHTS_PATH = path.join(DATA_DIR, 'model_weights.json');
const NORM_PARAMS_PATH = path.join(DATA_DIR, 'norm_params.json');
const MODEL_METRICS_PATH = path.join(DATA_DIR, 'model_metrics.json');


// ──────────────────────────────────────
// FEATURE / TARGET COLUMN DEFINITIONS
// ──────────────────────────────────────
const INPUT_COLUMNS = [
  'visitor_count',
  'zone_a_demand',
  'zone_b_demand',
  'zone_c_demand',
  'venue_load',
  'transit_load',
  'parking_load',
  'hotel_load',
  'rain_factor',
  'transit_disruption',
  'parking_reduction',
  'venue_delay',
  'visitor_growth'
];

const OUTPUT_COLUMNS = [
  'future_zone_a_demand',
  'future_zone_b_demand',
  'future_zone_c_demand'
];

// Event phase one-hot encoding
const PHASE_MAP = { 'INGRESS': 0, 'PEAK': 1, 'EGRESS': 2 };

// ──────────────────────────────────────
// CSV PARSER
// ──────────────────────────────────────
function parseCSV(csvPath) {
  const raw = fs.readFileSync(csvPath, 'utf8');
  const lines = raw.trim().split('\n');
  const headers = lines[0].split(',').map(h => h.trim());
  
  const records = [];
  for (let i = 1; i < lines.length; i++) {
    const vals = lines[i].split(',');
    if (vals.length !== headers.length) continue;
    
    const row = {};
    headers.forEach((h, idx) => {
      const v = vals[idx].trim();
      row[h] = isNaN(v) ? v : parseFloat(v);
    });
    records.push(row);
  }
  
  return records;
}

// ──────────────────────────────────────
// NORMALIZATION (Min-Max → [0, 1])
// ──────────────────────────────────────
function computeNormParams(records) {
  const allCols = [...INPUT_COLUMNS, ...OUTPUT_COLUMNS];
  const params = {};
  
  for (const col of allCols) {
    const values = records.map(r => r[col]).filter(v => typeof v === 'number');
    const min = Math.min(...values);
    const max = Math.max(...values);
    params[col] = { min, max, range: max - min || 1 };
  }
  
  return params;
}

function normalize(value, col, params) {
  const p = params[col];
  return (value - p.min) / p.range;
}

function denormalize(value, col, params) {
  const p = params[col];
  return value * p.range + p.min;
}

// ──────────────────────────────────────
// DATA PREPARATION
// ──────────────────────────────────────
function prepareTrainingData(records, normParams) {
  const trainingData = [];
  
  for (const record of records) {
    // Build input vector
    const input = {};
    INPUT_COLUMNS.forEach((col, idx) => {
      input[`f${idx}`] = normalize(record[col], col, normParams);
    });
    
    // One-hot encode event_phase
    const phase = PHASE_MAP[record.event_phase] ?? 0;
    input['f13'] = phase === 0 ? 1 : 0; // INGRESS
    input['f14'] = phase === 1 ? 1 : 0; // PEAK
    input['f15'] = phase === 2 ? 1 : 0; // EGRESS
    
    // Build output vector
    const output = {};
    OUTPUT_COLUMNS.forEach((col, idx) => {
      output[`t${idx}`] = normalize(record[col], col, normParams);
    });
    
    trainingData.push({ input, output });
  }
  
  return trainingData;
}

// ──────────────────────────────────────
// MODEL STATE (in-memory singleton)
// ──────────────────────────────────────
let loadedNet = null;
let loadedNormParams = null;

/**
 * Train the neural network on CSV data and save weights
 * @param {Object} options Training options
 * @returns {Object} Training result with error metrics
 */
export async function trainModel(options = {}) {
  const {
    maxSamples = 15000,    // Cap training samples for speed
    iterations = 300,       // Training epochs
    learningRate = 0.01,
    errorThresh = 0.005,
    logPeriod = 50,
    log = true
  } = options;
  
  console.log('\n══════════════════════════════════════════');
  console.log('  EVENTTWIN ML MODEL — TRAINING');
  console.log('══════════════════════════════════════════');
  console.log(`CSV Source : ${TRAINING_CSV}`);
  
  // 1. Load CSV
  const records = parseCSV(TRAINING_CSV);
  console.log(`Total rows : ${records.length.toLocaleString()}`);
  
  // 2. Shuffle and subsample for training efficiency
  const shuffled = records.sort(() => Math.random() - 0.5);
  const trainRecords = shuffled.slice(0, Math.min(maxSamples, shuffled.length));
  console.log(`Training on: ${trainRecords.length.toLocaleString()} samples`);
  
  // 3. Compute normalization params from FULL dataset
  const normParams = computeNormParams(records);
  console.log(`Features   : ${INPUT_COLUMNS.length} numeric + 3 one-hot (event_phase)`);
  console.log(`Targets    : ${OUTPUT_COLUMNS.join(', ')}`);
  
  // 4. Prepare normalized training data
  const trainingData = prepareTrainingData(trainRecords, normParams);
  
  // 5. Dynamically import brain.js
  const brain = await import('brain.js');
  const NeuralNetwork = brain.default?.NeuralNetwork || brain.NeuralNetwork;
  
  // 6. Create and train the network
  const net = new NeuralNetwork({
    hiddenLayers: [26, 16],
    activation: 'sigmoid',
    learningRate
  });
  
  console.log(`\nArchitecture: Input(16) → Hidden(26) → Hidden(16) → Output(3)`);
  console.log(`Training started... (max ${iterations} iterations, error threshold ${errorThresh})\n`);
  
  const startTime = Date.now();
  
  const result = net.train(trainingData, {
    iterations,
    errorThresh,
    log: log ? (stats) => console.log(`  Iteration ${stats.iterations}: error = ${stats.error.toFixed(6)}`) : false,
    logPeriod
  });
  
  const durationSec = ((Date.now() - startTime) / 1000).toFixed(1);
  
  console.log(`\n✅ Training complete in ${durationSec}s`);
  console.log(`   Final error: ${result.error.toFixed(6)}`);
  console.log(`   Iterations : ${result.iterations}`);
  
  // 7. Save model weights
  const weightsJSON = net.toJSON();
  fs.writeFileSync(MODEL_WEIGHTS_PATH, JSON.stringify(weightsJSON, null, 2));
  console.log(`   Weights saved → ${MODEL_WEIGHTS_PATH}`);
  
  // 8. Save normalization params
  fs.writeFileSync(NORM_PARAMS_PATH, JSON.stringify(normParams, null, 2));
  console.log(`   Norm params → ${NORM_PARAMS_PATH}`);
  
  // 9. Quick validation on 5 random holdout samples
  const holdout = shuffled.slice(maxSamples, maxSamples + 5);
  if (holdout.length > 0) {
    console.log(`\n── VALIDATION (${holdout.length} holdout samples) ──`);
    const validationData = prepareTrainingData(holdout, normParams);
    
    let totalError = 0;
    for (let i = 0; i < validationData.length; i++) {
      const predicted = net.run(validationData[i].input);
      const actual = validationData[i].output;
      
      const errors = OUTPUT_COLUMNS.map((col, idx) => {
        const predVal = Math.round(denormalize(predicted[`t${idx}`], col, normParams));
        const actualVal = Math.round(denormalize(actual[`t${idx}`], col, normParams));
        return Math.abs(predVal - actualVal);
      });
      
      const avgError = errors.reduce((s, e) => s + e, 0) / errors.length;
      totalError += avgError;
      
      console.log(`  Sample ${i + 1}: avg absolute error = ${avgError.toFixed(0)} visitors`);
    }
    
    console.log(`  Mean absolute error: ${(totalError / holdout.length).toFixed(0)} visitors`);
  }
  
  // Update in-memory model
  loadedNet = net;
  loadedNormParams = normParams;
  
  return {
    error: result.error,
    iterations: result.iterations,
    durationSec: parseFloat(durationSec),
    modelPath: MODEL_WEIGHTS_PATH,
    normParamsPath: NORM_PARAMS_PATH
  };
}

/**
 * Load a previously trained model from disk
 * @returns {boolean} true if model loaded successfully
 */
export async function loadTrainedModel() {
  if (!fs.existsSync(MODEL_WEIGHTS_PATH) || !fs.existsSync(NORM_PARAMS_PATH)) {
    console.log('[MLModel] No trained model found. Run trainModel.js first.');
    return false;
  }
  
  try {
    const brain = await import('brain.js');
    const NeuralNetwork = brain.default?.NeuralNetwork || brain.NeuralNetwork;
    
    const weightsJSON = JSON.parse(fs.readFileSync(MODEL_WEIGHTS_PATH, 'utf8'));
    const normParams = JSON.parse(fs.readFileSync(NORM_PARAMS_PATH, 'utf8'));
    
    const net = new NeuralNetwork();
    net.fromJSON(weightsJSON);
    
    loadedNet = net;
    loadedNormParams = normParams;
    
    console.log('[MLModel] ✅ Trained model loaded from disk.');
    return true;
  } catch (err) {
    console.error('[MLModel] Failed to load trained model:', err.message);
    return false;
  }
}

/**
 * Check if a trained model is available (in-memory or on disk)
 */
export function isModelAvailable() {
  if (loadedNet && loadedNormParams) return true;
  return fs.existsSync(MODEL_WEIGHTS_PATH) && fs.existsSync(NORM_PARAMS_PATH);
}

/**
 * Run inference on the trained model
 * 
 * @param {Object} currentState - Current canonical event state
 * @param {Object} scenarioParams - Scenario disruption parameters
 * @param {number[]} horizonsMinutes - Prediction horizons [15, 30, 45]
 * @returns {Object} Forecast map keyed by `${horizon}min`, same structure as fallbackForecast
 */
export async function runInference(currentState, scenarioParams = {}, horizonsMinutes = [15, 30, 45]) {
  // Ensure model is loaded
  if (!loadedNet || !loadedNormParams) {
    const loaded = await loadTrainedModel();
    if (!loaded) {
      throw new Error('No trained ML model available. Run: node server/prediction/trainModel.js');
    }
  }
  
  const normParams = loadedNormParams;
  const net = loadedNet;
  
  // Extract current state values with fallbacks
  const loads = currentState?.loads || {};
  const totalVisitors = currentState?.totalVisitors || 500000;
  const zoneBreakdown = currentState?.zoneBreakdown || {
    zoneA: Math.round(totalVisitors * 0.52),
    zoneB: Math.round(totalVisitors * 0.30),
    zoneC: Math.round(totalVisitors * 0.18)
  };
  
  // Scenario parameter extraction
  const rainFactor = scenarioParams.rainImpactPct ?? scenarioParams.rain_factor ?? 0;
  const transitDisruption = scenarioParams.transitReductionPct ?? scenarioParams.transit_disruption ?? 0;
  const parkingReduction = scenarioParams.parkingReductionPct ?? scenarioParams.parking_reduction ?? 0;
  const venueDelay = scenarioParams.venueDelayMinutes ?? scenarioParams.venue_delay ?? 0;
  const visitorGrowth = scenarioParams.visitorGrowthPct ?? scenarioParams.visitorIncreasePct ?? 5;
  
  const forecast = {};
  
  for (const horizon of horizonsMinutes) {
    // Scale visitor growth proportionally to horizon
    const horizonScale = horizon / 30.0; // 30min = baseline
    const effectiveGrowth = Math.round(visitorGrowth * horizonScale);
    
    // Build feature vector
    const rawInput = {
      visitor_count: totalVisitors,
      zone_a_demand: zoneBreakdown.zoneA,
      zone_b_demand: zoneBreakdown.zoneB,
      zone_c_demand: zoneBreakdown.zoneC,
      venue_load: loads.venueLoad ?? 84,
      transit_load: loads.transitLoad ?? 91,
      parking_load: loads.parkingLoad ?? 78,
      hotel_load: loads.hotelOccupancy ?? 81,
      rain_factor: rainFactor,
      transit_disruption: transitDisruption,
      parking_reduction: parkingReduction,
      venue_delay: venueDelay,
      visitor_growth: effectiveGrowth
    };
    
    // Normalize input
    const input = {};
    INPUT_COLUMNS.forEach((col, idx) => {
      input[`f${idx}`] = normalize(rawInput[col], col, normParams);
    });
    
    // Default to PEAK phase for inference (most conservative)
    input['f13'] = 0; // INGRESS
    input['f14'] = 1; // PEAK
    input['f15'] = 0; // EGRESS
    
    // Run neural network
    const rawOutput = net.run(input);
    
    // Denormalize outputs
    const futureZoneA = Math.round(denormalize(rawOutput['t0'], OUTPUT_COLUMNS[0], normParams));
    const futureZoneB = Math.round(denormalize(rawOutput['t1'], OUTPUT_COLUMNS[1], normParams));
    const futureZoneC = Math.round(denormalize(rawOutput['t2'], OUTPUT_COLUMNS[2], normParams));
    const futureTotal = futureZoneA + futureZoneB + futureZoneC;
    
    // Derive load percentages from zone demand predictions
    // Zone A load correlates with venue capacity utilization
    const zoneACapacity = 300000; // Zone A effective capacity
    const zoneBCapacity = 180000;
    const zoneCCapacity = 120000;
    
    const projectedVenueLoad = Math.min(150, Math.max(0, Math.round((futureZoneA / zoneACapacity) * 100)));
    const projectedTransitLoad = Math.min(150, Math.max(0, Math.round((futureZoneB / zoneBCapacity) * 100 * (1 + transitDisruption / 100 * 0.3))));
    const projectedParkingLoad = Math.min(150, Math.max(0, Math.round(
      (rawInput.parking_load || 78) * (futureTotal / totalVisitors) * (1 + parkingReduction / 100 * 0.35)
    )));
    const projectedHotelLoad = Math.min(100, Math.max(0, Math.round(
      (rawInput.hotel_load || 81) * Math.pow(futureTotal / totalVisitors, 0.5)
    )));
    const projectedMobilityLoad = Math.round(projectedTransitLoad * 0.8 + 55 * 0.2);
    
    const maxZoneLoad = Math.max(projectedVenueLoad, projectedTransitLoad * 0.9, 45);
    const minZoneLoad = Math.min(projectedVenueLoad, projectedTransitLoad * 0.9, 45);
    const demandImbalance = Math.max(0, maxZoneLoad - minZoneLoad);
    
    // Import stress calculator
    const { calculateEventTwinStressIndex } = await import('../simulationEngine.js');
    const stress = calculateEventTwinStressIndex({
      mobilityLoad: projectedMobilityLoad,
      venueLoad: projectedVenueLoad,
      parkingLoad: projectedParkingLoad,
      hotelOccupancy: projectedHotelLoad,
      demandImbalance
    });
    
    const overloadMinutes = projectedVenueLoad >= 90
      ? Math.max(10, Math.round(60 - (projectedVenueLoad - 90) * 1.5 - horizon))
      : null;
    
    // Build zone-level predictions (same format as fallback)
    const predictions = [
      {
        id: `pred_zone_a_${horizon}m`,
        zone: "Zone A (Core Arena - JWCC BKC)",
        current: rawInput.venue_load,
        predicted: projectedVenueLoad,
        expectedMinutes: overloadMinutes,
        status: projectedVenueLoad >= 100 ? "CRITICAL" : projectedVenueLoad >= 85 ? "HIGH" : "NORMAL",
        explanation: `ML model predicts Zone A at ${projectedVenueLoad}% load in +${horizon}m (${futureZoneA.toLocaleString()} visitors).`,
        suggestedAction: projectedVenueLoad >= 85
          ? "Divert 15% inbound traffic to Zone C concourses and activate staggered entry."
          : "Maintain standard ingress flow."
      },
      {
        id: `pred_zone_b_${horizon}m`,
        zone: "Zone B (Bandra/Santacruz Artery)",
        current: rawInput.transit_load,
        predicted: Math.round(projectedTransitLoad * 0.9),
        expectedMinutes: projectedTransitLoad >= 90 ? Math.max(20, 60 - horizon) : null,
        status: projectedTransitLoad >= 90 ? "HIGH" : "NORMAL",
        explanation: `ML model predicts Zone B transit corridor at ${Math.round(projectedTransitLoad * 0.9)}% load at +${horizon}m.`,
        suggestedAction: projectedTransitLoad >= 90
          ? "Reroute selected express shuttles via Kalina-Kurla bypass."
          : "Monitor suburban line headway."
      },
      {
        id: `pred_zone_c_${horizon}m`,
        zone: "Zone C (Kalina Spillover Hub)",
        current: 48,
        predicted: Math.min(85, Math.round((futureZoneC / zoneCCapacity) * 100)),
        expectedMinutes: null,
        status: "AVAILABLE CAPACITY",
        freeParkingBays: Math.max(5000, Math.round(8250 - futureZoneC / 20)),
        explanation: `ML model predicts Zone C at ${Math.min(85, Math.round((futureZoneC / zoneCCapacity) * 100))}% load at +${horizon}m — surplus capacity available.`,
        suggestedAction: "Ready to absorb diverted visitors and overflow vehicles."
      }
    ];
    
    forecast[`${horizon}min`] = {
      horizonMinutes: horizon,
      projectedTime: new Date(Date.now() + horizon * 60000).toISOString(),
      method: "ML_NEURAL_NETWORK",
      isML: true,
      disclaimer: "Prediction generated by trained brain.js neural network on 20K synthetic samples from simulationEngine.",
      totalVisitors: futureTotal,
      zoneBreakdown: {
        zoneA: futureZoneA,
        zoneB: futureZoneB,
        zoneC: futureZoneC
      },
      loads: {
        venueLoad: projectedVenueLoad,
        transitLoad: projectedTransitLoad,
        parkingLoad: projectedParkingLoad,
        hotelOccupancy: projectedHotelLoad,
        mobilityLoad: projectedMobilityLoad,
        demandImbalance
      },
      stressIndex: stress.compositeStress,
      stressBreakdown: stress.breakdown,
      criticalAreasCount: (projectedVenueLoad >= 90 ? 1 : 0) + (projectedTransitLoad >= 90 ? 1 : 0) + (projectedParkingLoad >= 90 ? 1 : 0),
      predictions
    };
  }
  
  return forecast;
}

/**
 * Returns recorded model training metrics, or null if not available
 */
export function getModelMetrics() {
  if (fs.existsSync(MODEL_METRICS_PATH)) {
    try {
      return JSON.parse(fs.readFileSync(MODEL_METRICS_PATH, 'utf8'));
    } catch (e) {
      return null;
    }
  }
  return null;
}

